#!/usr/bin/env python3
"""R19 three-runner native metadata-retention physical/CPU proof.

Read only SHA-verified GitHub artifacts; original invalid no-server run is NOT
included. Keep physical 17x read amplification separate from wall/CPU effects
and compare performance only within runner A/B/B/A phases.
"""
import argparse
import hashlib
import json
import math
import pathlib
import statistics
import zipfile

SOURCE='52529f0c711566d696917678bf15e7068772fdde'
BINARY='f0a2fa1f814c58853f43423705cac10ab9df3bfe5887e27ebe9620ba7cb9660e'
RETIRED_SHA='fc6ff8bf4ee1842b2f31e787d8cb336801bc59601c98ff249bdb0f6d16232267'
LIVE_SHA='df80189979bdc9ae0ba3ec0c4103f42444d703ef5948cfa5929989ae28b115d6'
CASES=['broad','project_p0']
FIELDS=['wall_p50_ms','query_cpu_p50_ms','read_rows_p50','read_bytes_p50']
PHASES={'A0':'tslab_r19_clean','B1':'tslab_r19_retained',
        'B2':'tslab_r19_retained','A3':'tslab_r19_clean'}


def verify(path):
    path=pathlib.Path(path)
    local_sha=hashlib.sha256(path.read_bytes()).hexdigest()
    with zipfile.ZipFile(path) as z:
        names=set(z.namelist())
        mandatory={'report.json','build-info.txt','script-sha256.txt',
                   'archive-verify.txt','binary-verify.txt','workflow-head.txt','console.log'}
        if not mandatory<=names:
            raise AssertionError(f'{path}: missing files {mandatory-names}')
        report=json.loads(z.read('report.json'))
        build=z.read('build-info.txt').decode()
        manifest=z.read('script-sha256.txt').decode()
        bincheck=z.read('binary-verify.txt').decode()
        archcheck=z.read('archive-verify.txt').decode()
        git_head=z.read('workflow-head.txt').decode().strip()
        if SOURCE not in build or 'optimization=O1 unmodified stock source no lab patches' not in build:
            raise AssertionError(f'{path}: stock binary build provenance differs')
        if 'clickhouse: OK' not in bincheck or 'OK' not in archcheck:
            raise AssertionError(f'{path}: source binary/archive checks not proven')
        if 'r19_expired_metadata_native.py' not in manifest:
            raise AssertionError(f'{path}: R19 code SHA absent')
        if len(git_head)!=40:
            raise AssertionError(f'{path}: workflow commit SHA absent')
    if not report.get('passed') or report.get('errors'):
        raise AssertionError(f'{path}: source experiment invalid')
    if report.get('source_sha')!=SOURCE or report.get('retired')!=48000 or report.get('live')!=2000:
        raise AssertionError(f'{path}: fixture/source changed')
    if report.get('input_sha256')!={'retired':RETIRED_SHA,'live_both':LIVE_SHA}:
        raise AssertionError(f'{path}: mismatched generated bytes')
    if not report.get('samples_deleted_by','').startswith('explicit DROP PARTITION'):
        raise AssertionError(f'{path}: old samples not manually removed')
    if report['physical'].get('dropped_partition_id')!='202608':
        raise AssertionError(f'{path}: wrong retired partition')
    a=report['physical']['after']
    clean=a['tslab_r19_clean']
    old=a['tslab_r19_retained']
    for field in ('tags','timeranges'):
        if clean[field]['count']!=2000 or old[field]['count']!=50000:
            raise AssertionError(f'{path}: old {field} did not persist')
    if clean['samples']['count']!=2000 or old['samples']['count']!=2000:
        raise AssertionError(f'{path}: active sample point mismatch')
    if report['physical']['active_sample_bytes']['tslab_r19_clean'] != \
       report['physical']['active_sample_bytes']['tslab_r19_retained']:
        raise AssertionError(f'{path}: clean and retained SAMPLES byte size differs')
    livepart=old['samples']['parts']
    if len(livepart)!=1 or livepart[0]['partition_id']!='202610':
        raise AssertionError(f'{path}: old sample partition still present')
    if len(report.get('trials',[]))!=len(CASES)*len(PHASES)*(3+10):
        raise AssertionError(f'{path}: incomplete native request suite')
    for kind in CASES:
        p=report['phases'][kind]
        if set(p)!=set(PHASES):
            raise AssertionError(f'{path}: missing native phases')
        for phase,table in PHASES.items():
            if p[phase]['table']!=table or p[phase]['summary']['count']!=10:
                raise AssertionError(f'{path}: missing timed native requests')
        if kind not in report.get('comparisons',{}):
            raise AssertionError(f'{path}: incomplete matched ABBA')
        metric=report['comparisons'][kind]
        for key in FIELDS:
            d=metric[key]
            if d['retained_over_clean']<=0 or d['clean']<=0 or d['retained']<=0:
                raise AssertionError(f'{path}: invalid timing/rows')
            if key in ('wall_p50_ms','query_cpu_p50_ms') and d['clean_AA_drift']>.25:
                raise AssertionError(f'{path}: control drift >25% {kind}/{key}')
        if abs(metric['read_rows_p50']['retained_over_clean']-17)>1e-9:
            raise AssertionError(f'{path}: read rows did not scale 17x')
        if metric['read_bytes_p50']['retained_over_clean']<16:
            raise AssertionError(f'{path}: expected physical metadata read-byte growth missing')
    if not all(x['cpu_ms']>0 and x['query_sha256'] and x['values']
               for x in report['trials']):
        raise AssertionError(f'{path}: native values/CPU missing')
    return {'source_zip':str(path),'local_zip_sha':local_sha,
            'script_manifest':manifest,'build_head':git_head,
            'physical':report['physical']['after'],
            'comparisons':report['comparisons'],
            'query_count':len(report['trials'])}


def reduce(runs):
    if len(runs)!=3 or len({r['local_zip_sha'] for r in runs})!=3:
        raise AssertionError('Three distinct successful full native artifacts required')
    if len({r['script_manifest'] for r in runs})!=1:
        raise AssertionError('Source code hashes differ across runner artifacts')
    reports={'question_id':'R19-expired-samples-retained-tags-timeranges-v1',
             'source_sha':SOURCE,'binary_sha256':BINARY,'live_fixture_sha256':LIVE_SHA,
             'retired_fixture_sha256':RETIRED_SHA,'valid':True,
             'historical_excluded':'41635086542 (INFRA_FAIL connection refused)',
             'artifact_zip_hashes':[r['local_zip_sha'] for r in runs],
             'ratios':{},'decision':'INCONCLUSIVE'}
    supported=[]
    for case in CASES:
        reports['ratios'][case]={}
        for key in FIELDS:
            ratios=[r['comparisons'][case][key]['retained_over_clean'] for r in runs]
            drifts=[r['comparisons'][case][key]['clean_AA_drift'] for r in runs]
            if any(v<=0 for v in ratios):
                raise AssertionError('Nonpositive effect/size')
            reports['ratios'][case][key]={'per_runner_retained_over_clean':ratios,
                 'geometric_mean':round(math.exp(statistics.mean(math.log(v) for v in ratios)),5),
                 'control_drifts':drifts}
            if key in ('wall_p50_ms','query_cpu_p50_ms'):
                supported.append(all(v>1+max(.05,d) for v,d in zip(ratios,drifts)))
    reports['physical_retention_reproduced']=True
    reports['all_query_cpu_wall_regressions_reproduced']=all(supported)
    reports['decision']='REPLICATED_LAB_EFFECT' if all(supported) else 'REPLICATED_PHYSICAL_EFFECT_ONLY'
    reports['limitations']=[
        'Manual DROP PARTITION models the effect of sample retirement; no asynchronous TTL merge/execution claim',
        'Three synthetic GitHub runners, 2000 live plus 48000 expired single-sample IDs, one metric and two selectors only',
        'No safe TAGS/TimeRanges garbage collector implemented or tested; series can resume or arrive late',
        'Same stock LLVM22 O1/glibc binary, not optimized production jemalloc or remote storage',
        'Per-runner A/B/B/A, 10 measured requests per phase, no concurrent writes during query timing']
    return reports


def main():
    p=argparse.ArgumentParser()
    p.add_argument('--artifact',action='append',required=True)
    p.add_argument('--output',required=True)
    args=p.parse_args()
    if len(args.artifact)!=3:
        raise SystemExit('Require exactly 3 complete original/replicated ZIP artifacts')
    report=reduce([verify(path) for path in args.artifact])
    path=pathlib.Path(args.output)
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(json.dumps(report,indent=2,sort_keys=True)+'\n')
    print('R19_REDUCER',json.dumps({'valid':report['valid'],
         'decision':report['decision'],'ratios':report['ratios']},
          separators=(',',':')),flush=True)


if __name__=='__main__':
    main()
